const input = $json;
const maskPhone = (value) => String(value || '').replace(/(9715\d{2})\d{4}(\d{3})/g, '$1****$2');
const redact = (value) => {
  if (value == null) return value;
  if (typeof value === 'string') return maskPhone(value).replace(/(sk-[A-Za-z0-9_-]{12,}|Bearer\s+[A-Za-z0-9._-]+|whatsapp_access_token\s*[:=]\s*\S+|api[_-]?key\s*[:=]\s*\S+)/gi, '[REDACTED_SECRET]').replace(/\b\d{12,19}\b/g, '[REDACTED_NUMBER]');
  if (Array.isArray(value)) return value.map(redact);
  if (typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, val]) => [/token|secret|password|apiKey|authorization|cookie/i.test(key) ? [key, '[REDACTED_SECRET]'] : [key, redact(val)]]));
  }
  return value;
};
const redacted = redact(input);
return [{ json: { ...redacted, originalMessageId: input.wamid || input.messageId || input.message_id || '', conversationId: input.conversationId || input.conversation_id || input.memory?.conversationId || '', customerId: input.customerId || input.customer_id || input.identity?.customer?.id || '', correlationId: input.correlationId || input.correlation_id || 'corr_' + Date.now(), workflowExecutionId: String($execution.id || '') } }];
